1	/**
2	 * The fan-out hub: one domain event becomes in-app rows, an email draft and/or a digest entry, filtered by each recipient's preferences.
3	 *
4	 * Must call (do not reimplement): assertCan, assertOrgScope, isEnabled, subscribe
5	 */
6	import { subscribe } from "@/lib/event-bus";
7	import { isEnabled } from "@/lib/feature-flags";
8	import { assertCan } from "@/lib/permissions";
9	import { assertOrgScope } from "@/lib/tenant";
10	import * as issueRepo from "@/server/repositories/issue-repository";
11	import * as notificationRepo from "@/server/repositories/notification-repository";
12	import * as orgRepo from "@/server/repositories/organization-repository";
13	import * as preferenceRepo from "@/server/repositories/notification-preference-repository";
14	import { toIsoTimestamp } from "@/types/common";
15	import { notificationResource, requireFound } from "./_support";
16	import type {
17	  ListNotificationsInput,
18	  MarkNotificationReadInput,
19	  UpdateNotificationPreferenceInput,
20	} from "@/schemas/notification";
21	import type { OrgId, Page, UserId } from "@/types/common";
22	import type { FlagContext } from "@/types/feature-flag";
23	import type { Actor } from "@/types/member";
24	import type {
25	  Notification,
26	  NotificationChannel,
27	  NotificationKind,
28	  NotificationPreference,
29	} from "@/types/notification";
30	
31	export type NotificationPayload = {
32	  title: string;
33	  body: string;
34	  href: string;
35	  actorId: UserId | null;
36	};
37	
38	/** Channels used when a recipient has never touched their preferences. */
39	const DEFAULT_CHANNELS: readonly NotificationChannel[] = ["in_app", "email"];
40	
41	/**
42	 * Writes one notification row per recipient, each with the channel set that
43	 * recipient's preferences allow. A recipient who has muted every channel is
44	 * skipped entirely rather than given a row nobody will ever see.
45	 */
46	export async function notify(
47	  orgId: OrgId,
48	  kind: NotificationKind,
49	  recipients: readonly UserId[],
50	  payload: NotificationPayload,
51	): Promise<readonly Notification[]> {
52	  if (recipients.length === 0) return [];
53	
54	  const org = await orgRepo.findOrgById(orgId);
55	  const flags: FlagContext = {
56	    orgId,
57	    userId: payload.actorId,
58	    plan: org?.plan ?? "free",
59	    role: null,
60	    overrides: org?.settings.enabledFlagOverrides,
61	  };
62	
63	  const rows = [];
64	
65	  for (const recipientId of new Set(recipients)) {
66	    if (recipientId === payload.actorId) continue;
67	
68	    const preference = await preferenceRepo.getPreference(
69	      orgId,
70	      recipientId,
71	      kind,
72	    );
73	    const channels = resolveChannels(preference, flags);
74	    if (channels.length === 0) continue;
75	
76	    rows.push({
77	      orgId,
78	      recipientId,
79	      kind,
80	      title: payload.title,
81	      body: payload.body,
82	      href: payload.href,
83	      actorId: payload.actorId,
84	      channels,
85	    });
86	  }
87	
88	  return notificationRepo.insertNotifications(orgId, rows);
89	}
90	
91	export async function listNotifications(
92	  actor: Actor,
93	  input: ListNotificationsInput,
94	): Promise<Page<Notification>> {
95	  assertOrgScope(actor, input.orgId);
96	  assertCan(
97	    actor,
98	    "notification:read",
99	    notificationResource(input.orgId, input.recipientId),
100	  );
101	  return notificationRepo.listNotifications(input);
102	}
103	
104	export async function markRead(
105	  actor: Actor,
106	  input: MarkNotificationReadInput,
107	): Promise<Notification> {
108	  assertOrgScope(actor, input.orgId);
109	  assertCan(
110	    actor,
111	    "notification:manage",
112	    notificationResource(input.orgId, actor.userId),
113	  );
114	  return notificationRepo.markRead(
115	    input.orgId,
116	    input.notificationId,
117	    toIsoTimestamp(new Date()),
118	  );
119	}
120	
121	export async function markAllRead(
122	  actor: Actor,
123	  orgId: OrgId,
124	): Promise<number> {
125	  assertOrgScope(actor, orgId);
126	  assertCan(
127	    actor,
128	    "notification:manage",
129	    notificationResource(orgId, actor.userId),
130	  );
131	  return notificationRepo.markAllRead(
132	    orgId,
133	    actor.userId,
134	    toIsoTimestamp(new Date()),
135	  );
136	}
137	
138	export async function updatePreference(
139	  actor: Actor,
140	  input: UpdateNotificationPreferenceInput,
141	): Promise<NotificationPreference> {
142	  assertOrgScope(actor, input.orgId);
143	  assertCan(
144	    actor,
145	    "notification:manage",
146	    notificationResource(input.orgId, input.userId),
147	  );
148	  return preferenceRepo.upsertPreference(input);
149	}
150	
151	/**
152	 * Turns a stored preference into the channels one notification will use.
153	 * `digestOnly` suppresses the immediate email but keeps the in-app row, and
154	 * the email channel additionally requires the org's `digest_email` plan flag.
155	 */
156	export function resolveChannels(
157	  preference: NotificationPreference | null,
158	  flags: FlagContext,
159	): readonly NotificationChannel[] {
160	  if (preference === null) return DEFAULT_CHANNELS;
161	
162	  const channels: NotificationChannel[] = [];
163	  if (preference.inApp) channels.push("in_app");
164	
165	  const emailAllowed =
166	    preference.email &&
167	    (!preference.digestOnly || isEnabled("digest_email", flags));
168	
169	  if (emailAllowed) channels.push("email");
170	  return channels;
171	}
172	
173	/**
174	 * The bus wiring. Attached at module load rather than from `event-registry`
175	 * because the fan-out has no other public entry point — importing this module
176	 * is what makes an org start receiving notifications.
177	 */
178	let registered = false;
179	
180	function registerFanOut(): void {
181	  if (registered) return;
182	  registered = true;
183	
184	  subscribe("issue.assigned", async (payload) => {
185	    await notify(payload.orgId, "issue_assigned", [payload.assigneeId], {
186	      title: "You were assigned an issue",
187	      body: `Issue ${payload.issueId} is now yours`,
188	      href: `/issues/${payload.issueId}`,
189	      actorId: payload.actorId,
190	    });
191	  });
192	
193	  subscribe("issue.overdue", async (payload) => {
194	    if (payload.assigneeId === null) return;
195	    await notify(payload.orgId, "issue_overdue", [payload.assigneeId], {
196	      title: "An issue is overdue",
197	      body: `Issue ${payload.issueId} was due ${payload.dueAt}`,
198	      href: `/issues/${payload.issueId}`,
199	      actorId: null,
200	    });
201	  });
202	
203	  subscribe("comment.created", async (payload) => {
204	    const issue = await issueRepo.findIssueById(payload.orgId, payload.issueId);
205	    const watchers = issue
206	      ? [issue.authorId, ...(issue.assigneeId ? [issue.assigneeId] : [])]
207	      : [];
208	
209	    await notify(payload.orgId, "comment_created", watchers, {
210	      title: "New comment",
211	      body: `A comment was added to issue ${payload.issueId}`,
212	      href: `/issues/${payload.issueId}`,
213	      actorId: payload.actorId,
214	    });
215	
216	    if (payload.mentionedUserIds.length > 0) {
217	      await notify(
218	        payload.orgId,
219	        "comment_mention",
220	        payload.mentionedUserIds,
221	        {
222	          title: "You were mentioned",
223	          body: `You were mentioned on issue ${payload.issueId}`,
224	          href: `/issues/${payload.issueId}`,
225	          actorId: payload.actorId,
226	        },
227	      );
228	    }
229	  });
230	
231	  subscribe("member.joined", async (payload) => {
232	    const org = requireFound(
233	      await orgRepo.findOrgById(payload.orgId),
234	      "Organization",
235	      payload.orgId,
236	    );
237	    await notify(payload.orgId, "member_joined", [org.ownerId], {
238	      title: "A new member joined",
239	      body: `${payload.userId} joined as ${payload.role}`,
240	      href: "/settings/members",
241	      actorId: payload.userId,
242	    });
243	  });
244	}
245	
246	registerFanOut();
